// Decide tone branch based on prior-meeting lookup.
const prior = $json && $json.meeting_id ? true : false;
const meeting = $('HubSpot — Pull Meeting + Owner').item.json.properties;
const contact = $('HubSpot — Pull Contact').item.json.properties;
const webhook = $('Webhook — HubSpot no-show event').item.json.body;

const tone = prior ? 'we_missed_you' : 'lets_reschedule';

return [{
  json: {
    contact_id: webhook.contactId,
    meeting_id: webhook.meetingId,
    owner_id: webhook.ownerId || meeting.hubspot_owner_id,
    email: contact.email,
    first_name: contact.firstname,
    last_name: contact.lastname,
    company: contact.company,
    job_title: contact.jobtitle,
    form_summary: contact.form_submission_summary || contact.recent_form_fill || null,
    meeting_title: meeting.hs_meeting_title,
    meeting_started_at: meeting.hs_meeting_start_time,
    tone,
    has_prior_meeting: prior,
    sequence_started_at: new Date().toISOString(),
  }
}];

