// Compose the same-day reschedule email body from the approved template + Claude opener.
const ctx = $('Build Personalization Context').item.json;
const owner = $('HubSpot — Pull AE Owner').item.json;
const claudeRaw = $json.content && $json.content[0] ? $json.content[0].text.trim() : 'FALLBACK';
const opener = claudeRaw === 'FALLBACK'
  ? `Sorry we didn\'t connect earlier — happy to find another window that works.`
  : claudeRaw;

// Two pre-picked slots: tomorrow 10:00 and tomorrow 14:00 in the AE's local TZ.
const tomorrow = new Date();
tomorrow.setUTCDate(tomorrow.getUTCDate() + 1);
const dateStr = tomorrow.toISOString().slice(0, 10);
const slot1 = `${dateStr} 10:00 (${owner.timeZone || 'local'})`;
const slot2 = `${dateStr} 14:00 (${owner.timeZone || 'local'})`;
const schedulingLink = owner.metadata && owner.metadata.schedulingLink
  ? owner.metadata.schedulingLink
  : `https://meetings.hubspot.com/${(owner.email || '').split('@')[0]}`;

const body = [
  `Hi ${ctx.first_name},`,
  '',
  opener,
  '',
  `Two windows that should work this week:`,
  `  • ${slot1}`,
  `  • ${slot2}`,
  '',
  `Pick one or grab any other slot here: ${schedulingLink}`,
  '',
  `— ${owner.firstName || 'The team'}`,
].join('\n');

return [{
  json: {
    ...ctx,
    ae_email: owner.email,
    ae_first_name: owner.firstName,
    scheduling_link: schedulingLink,
    subject: `Reschedule? Two times that work this week`,
    body,
    opener_used: opener,
    used_fallback: claudeRaw === 'FALLBACK',
  }
}];

// Step 2: 'value forward' email referencing a relevant resource.
const row = $json;
const resourceMap = {
  'we_missed_you': {
    title: 'How peer teams cut their no-show rate by half',
    url: 'https://example.com/resources/no-show-playbook',
  },
  'lets_reschedule': {
    title: 'A 5-minute teardown of the typical RevOps stack',
    url: 'https://example.com/resources/revops-stack-teardown',
  },
};
const resource = resourceMap[row.tone] || resourceMap['lets_reschedule'];

const body = [
  `Hi,`,
  '',
  `Sending one short thing in case it lands at the right time:`,
  `  ${resource.title} — ${resource.url}`,
  '',
  `If a quick walk-through would be more useful, reply with a window and I'll send a calendar hold.`,
  '',
  `— sent on behalf of ${row.ae_email}`,
].join('\n');

return [{
  json: {
    ...row,
    subject: `Worth 4 minutes — ${resource.title}`,
    body,
    next_step: 2,
    next_due_in_days: 5,
    completes_sequence: false,
  }
}];

// Step 3: soft close after a week. Final touch in the sequence.
const row = $json;
const body = [
  `Hi,`,
  '',
  `Closing the loop on this one — happy to reopen the thread if the timing shifts.`,
  `If you'd rather not hear from me again, just reply STOP and I'll mark the record.`,
  '',
  `— ${row.ae_email}`,
].join('\n');

return [{
  json: {
    ...row,
    subject: `Closing the loop`,
    body,
    next_step: 3,
    next_due_in_days: null,
    completes_sequence: true,
  }
}];

// Normalize an inbound reply and classify exit reason.
const from = ($json.from || '').match(/<([^>]+)>/)?.[1] || ($json.from || '').trim();
const subject = ($json.subject || '').toLowerCase();
const snippet = ($json.snippet || $json.text || '').toLowerCase();

let exit_reason;
if (/\b(stop|unsubscribe|opt[- ]?out|do not contact)\b/.test(snippet) || /unsubscribe/.test(subject)) {
  exit_reason = 'opt_out';
} else if (/\b(book(ed)?|schedul(ed|ing)|calendar|invite|works for me|how about)\b/.test(snippet)) {
  exit_reason = 'rescheduled_or_replied';
} else {
  exit_reason = 'human_reply';
}

return [{
  json: {
    candidate_email: from,
    subject: $json.subject,
    snippet: $json.snippet,
    received_at: $json.internalDate ? new Date(Number($json.internalDate)).toISOString() : new Date().toISOString(),
    exit_reason,
  }
}];
